package com.basiclab.iot.transform.runtime.service; import com.basiclab.iot.transform.core.domain.MappingRule; import com.basiclab.iot.transform.runtime.dal.TransformRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class MappingService { private final TransformRepository repository; public MappingService(TransformRepository repository){this.repository=repository;} public Collection<MappingRule> list(){return repository.listMappings();} public MappingRule get(String id){return repository.mapping(id);} }